def review_node(state: Dict[str, Any], runtime: Any) -> Dict[str, Any]:
    """Human-in-the-loop checkpoint.

    ``interrupt`` pauses the graph; the caller resumes with a dict:
    ``{"decision": "approve"|"reject"|"partial", "approved_ids": [...],
       "rejected_ids": [...], "notes": "..."}``.
    """
    enh = _enh(state)
    findings = state.get("findings") or []
    payload = {
        "type": "finding_review",
        "question": "模型对以下疑似图斑置信度不足，请复核后给出处置意见。",
        "confidence": state.get("confidence", {}).get("overall"),
        "reasons": (state.get("assessment") or {}).get("reasons", []),
        "findings": [
            {
                "id": f.get("id"),
                "area_m2": f.get("area_m2"),
                "mean_prob": f.get("mean_prob"),
                "confidence_level": f.get("confidence_level"),
                "flags": f.get("flags"),
                "centroid": f.get("centroid"),
                "bbox": f.get("bbox"),
            }
            for f in findings[:10]
        ],
        "resume_schema": {
            "decision": "approve | reject | partial",
            "approved_ids": ["F0001"],
            "rejected_ids": ["F0002"],
            "notes": "复核意见",
        },
    }
    decision = interrupt(payload)
    if isinstance(decision, str):
        decision = {"decision": decision}
    if not isinstance(decision, dict):
        decision = {"decision": "abstain", "notes": str(decision)}

    action = decision.get("decision", "approve")
    approved = set(decision.get("approved_ids") or [])
    rejected = set(decision.get("rejected_ids") or [])
    if action == "approve" and not approved and not rejected:
        approved = {f.get("id") for f in findings}
    if action == "reject" and not rejected:
        rejected = {f.get("id") for f in findings}

    updated = []
    for f in findings:
        item = dict(f)
        fid = item.get("id")
        if fid in approved:
            item["review_status"] = "approved"
            item["human_confirmed"] = True
        elif fid in rejected:
            item["review_status"] = "rejected"
            item["flags"] = list(dict.fromkeys(list(item.get("flags", [])) + ["human_rejected"]))
        elif action == "partial":
            item["review_status"] = "pending"
        updated.append(item)

    confidence = dict(state.get("confidence") or {})
    confidence["human_review"] = {
        "decision": action,
        "approved_ids": sorted(approved),
        "rejected_ids": sorted(rejected),
        "notes": decision.get("notes", ""),
    }
    assessment = dict(state.get("assessment") or {})
    assessment.update(
        {
            "needs_enhancement": False,
            "human_reviewed": True,
            "review_decision": decision,
            "review_required": False,
        }
    )
    enh = _remember(
        enh,
        "human_review",
        f"人工复核: {action}; 通过={sorted(approved)}; 驳回={sorted(rejected)}; 备注={decision.get('notes', '')}",
    )
    return {
        "findings": updated,
        "confidence": confidence,
        "assessment": assessment,
        "reviewed": True,
        "review_decision": decision,
        "enhancement": enh,
        "status": "reviewed",
        "audit": [
            _audit(
                "enhance.review",
                {
                    "decision": action,
                    "approved": sorted(approved),
                    "rejected": sorted(rejected),
                },
            )
        ],
    }

